-- clio-awards-entry-form-2026-10-07.sql
-- Seeds show_profiles.entry_form for the Clio Awards (row 24, show-level) and
-- inserts three category rows (Film, Integrated, Creative Effectiveness).
-- Design: Shortlist App/CLIO-AWARDS-ENTRY-FORM-DESIGN-2026-10-07.md (approved
-- with the Phase 2 GO decisions). Every label/limit/quote traces to
-- Award Show Research/EVIDENCE/Clio-Awards-2027-Entry-Form-Capture-2026-10-07.md
-- and the CE Entrant Brief PDF. No ON CONFLICT: the guards and the
-- (show_name, category_pattern) NULLS NOT DISTINCT unique index block a re-run.
-- Rollback: DELETE FROM show_profiles WHERE show_name = 'Clio Awards' AND category_pattern IN ('Film','Integrated','Creative Effectiveness'); UPDATE show_profiles SET entry_form = NULL WHERE id = 24;
BEGIN;

DO $guard$
BEGIN
  IF (SELECT count(*) FROM show_profiles
      WHERE id = 24 AND show_name = 'Clio Awards' AND category_pattern IS NULL AND entry_form IS NULL) <> 1 THEN
    RAISE EXCEPTION 'CLIO SEED: row 24 not in expected state';
  END IF;
  IF EXISTS (SELECT 1 FROM show_profiles WHERE show_name = 'Clio Awards' AND category_pattern IS NOT NULL) THEN
    RAISE EXCEPTION 'CLIO SEED: Clio Awards category rows already exist';
  END IF;
END $guard$;

UPDATE show_profiles SET entry_form = $j${"form_version": 2, "scoring_mode": "weighted", "entry_subject": "campaign", "primary_tool": "section_drafter", "overall": "weighted_average", "source_url": "Clio Awards 2027 entrant portal (new-entries.clios.com, login-walled), read 7 Oct 2026. Record: Award Show Research/EVIDENCE/Clio-Awards-2027-Entry-Form-Capture-2026-10-07.md", "verified_on": "2026-10-07", "notes": "Verified 7 Oct 2026 inside the Clio Awards 2027 entrant portal on 5 of 29 professional mediums: Out of Home, Public Relations, Film, Integrated, Creative Effectiveness. Out of Home and Public Relations use exactly this form. Film, Integrated and Creative Effectiveness have their own rows. The other 24 mediums are ASSUMED to use this form and are unverified until read in the portal; a medium with an extra written field (as Film and Integrated have) will be missing it here. The jury reads one written field, the Synopsis (2,500 characters), plus the work itself, which Shortlist cannot see, so this score is a read of the Synopsis only. The 100% weight on the Synopsis is a Shortlist modelling choice so the score has one input; Clio publishes no section weights for these mediums. All limits are characters, enforced by the portal as a hard maximum, not words.", "jury_programme_name": "Clio Awards", "jury_entry_noun": "Clio Awards", "jury_framing": "The Clio Awards are judged on the work itself (cover image, executions, and an optional case board and case study video) plus one written field, the Synopsis, which the entry portal labels \"FOR JUDGING PURPOSES ONLY\" and caps at 2,500 characters. You are reading only the Synopsis. You cannot see the work.", "subject_lens": "Score the Synopsis on what the portal asks it to do: \"state the main objective of the entry as concisely as possible\" and give the context a juror needs, \"including cultural background, insights on the creative process, and/or specific notes on what makes the entry unique in the medium entered.\" Reward a clear objective, real cultural or creative-process insight, and a specific case for what is new in this medium. Results are welcome where they help that case but are not the test. Penalise padding, generic claims, and a Synopsis that describes the campaign without saying why it is unique in the medium.", "jury_role": "senior creative juror", "jury_evidence_rule": "- Results are expected but do not dominate at this show: reward a result where it supports the case for the idea, and do not treat its absence as a gap, because results are not the test. Reward specificity about the objective, the cultural context and the creative process; penalise vague superlatives and claims of originality with nothing specific behind them.", "sections": [{"key": "entry_title", "label": "Entry Title", "weight": null, "word_limit": null, "scored": false, "sort_order": 0, "guidance": "The entry title is a short name for this entry. Keep it memorable, descriptive and short. Do not include the brand name, agency name, or medium type. Note: If your piece is awarded, the entry title will be listed on the trophy (maximum characters: 62).", "fields": [{"key": "title", "label": "Entry Title", "type": "short_text", "required": true, "char_limit": 62, "help": "The entry title is a short name for this entry. Keep it memorable, descriptive and short. Do not include the brand name, agency name, or medium type. Note: If your piece is awarded, the entry title will be listed on the trophy (maximum characters: 62)."}]}, {"key": "entry_brand", "label": "Entry Brand", "weight": null, "word_limit": null, "scored": false, "sort_order": 1, "guidance": "The entry brand is the brand, organization, or individual the entry is advertising. (maximum characters: 62).", "fields": [{"key": "brand", "label": "Entry Brand", "type": "short_text", "required": true, "char_limit": 62, "help": "The entry brand is the brand, organization, or individual the entry is advertising. (maximum characters: 62)."}]}, {"key": "synopsis", "label": "Synopsis", "weight": 100, "word_limit": null, "sort_order": 2, "guidance": "FOR JUDGING PURPOSES ONLY: Please state the main objective of the entry as concisely as possible. Please include any additional context needed; including cultural background, insights on the creative process, and/or specific notes on what makes the entry unique in the medium entered.", "fields": [{"key": "synopsis", "label": "Synopsis", "type": "long_text", "required": false, "char_limit": 2500, "help": "FOR JUDGING PURPOSES ONLY: Please state the main objective of the entry as concisely as possible. Please include any additional context needed; including cultural background, insights on the creative process, and/or specific notes on what makes the entry unique in the medium entered."}]}]}$j$::jsonb
WHERE id = 24 AND entry_form IS NULL;

INSERT INTO show_profiles (show_name, category_pattern, judging_philosophy, scoring_emphasis,
  language_guidance, common_mistakes, jury_composition_notes, medal_culture, resonant_language,
  red_flag_language, gold_standard_profile, entry_form)
SELECT 'Clio Awards', v.cat, sp.judging_philosophy, sp.scoring_emphasis, sp.language_guidance,
  sp.common_mistakes, sp.jury_composition_notes, sp.medal_culture, sp.resonant_language,
  sp.red_flag_language, sp.gold_standard_profile, v.form
FROM show_profiles sp
CROSS JOIN (VALUES
  ('Film', $j${"form_version": 2, "scoring_mode": "weighted", "entry_subject": "campaign", "primary_tool": "section_drafter", "overall": "weighted_average", "source_url": "Clio Awards 2027 entrant portal (new-entries.clios.com, login-walled), read 7 Oct 2026. Record: Award Show Research/EVIDENCE/Clio-Awards-2027-Entry-Form-Capture-2026-10-07.md", "verified_on": "2026-10-07", "notes": "Film, verified 7 Oct 2026 in the Clio Awards 2027 entrant portal (draft 243065): the show-level form plus one field, Where Did This Run? (500 characters, no asterisk shown), which is drafted but not scored. Synopsis 2,500 characters, wording identical to Out of Home and Public Relations. The 100% weight on the Synopsis is a Shortlist modelling choice; Clio publishes no section weights for this medium. Shortlist cannot see the work, so the score is a read of the Synopsis only.", "jury_programme_name": "Clio Awards", "jury_entry_noun": "Clio Awards", "jury_framing": "The Clio Awards are judged on the work itself (cover image, executions, and an optional case board and case study video) plus one written field, the Synopsis, which the entry portal labels \"FOR JUDGING PURPOSES ONLY\" and caps at 2,500 characters. You are reading only the Synopsis. You cannot see the work.", "subject_lens": "Score the Synopsis on what the portal asks it to do: \"state the main objective of the entry as concisely as possible\" and give the context a juror needs, \"including cultural background, insights on the creative process, and/or specific notes on what makes the entry unique in the medium entered.\" Reward a clear objective, real cultural or creative-process insight, and a specific case for what is new in this medium. Results are welcome where they help that case but are not the test. Penalise padding, generic claims, and a Synopsis that describes the campaign without saying why it is unique in the medium.", "jury_role": "senior creative juror", "jury_evidence_rule": "- Results are expected but do not dominate at this show: reward a result where it supports the case for the idea, and do not treat its absence as a gap, because results are not the test. Reward specificity about the objective, the cultural context and the creative process; penalise vague superlatives and claims of originality with nothing specific behind them.", "sections": [{"key": "entry_title", "label": "Entry Title", "weight": null, "word_limit": null, "scored": false, "sort_order": 0, "guidance": "The entry title is a short name for this entry. Keep it memorable, descriptive and short. Do not include the brand name, agency name, or medium type. Note: If your piece is awarded, the entry title will be listed on the trophy (maximum characters: 62).", "fields": [{"key": "title", "label": "Entry Title", "type": "short_text", "required": true, "char_limit": 62, "help": "The entry title is a short name for this entry. Keep it memorable, descriptive and short. Do not include the brand name, agency name, or medium type. Note: If your piece is awarded, the entry title will be listed on the trophy (maximum characters: 62)."}]}, {"key": "entry_brand", "label": "Entry Brand", "weight": null, "word_limit": null, "scored": false, "sort_order": 1, "guidance": "The entry brand is the brand, organization, or individual the entry is advertising. (maximum characters: 62).", "fields": [{"key": "brand", "label": "Entry Brand", "type": "short_text", "required": true, "char_limit": 62, "help": "The entry brand is the brand, organization, or individual the entry is advertising. (maximum characters: 62)."}]}, {"key": "synopsis", "label": "Synopsis", "weight": 100, "word_limit": null, "sort_order": 2, "guidance": "FOR JUDGING PURPOSES ONLY: Please state the main objective of the entry as concisely as possible. Please include any additional context needed; including cultural background, insights on the creative process, and/or specific notes on what makes the entry unique in the medium entered.", "fields": [{"key": "synopsis", "label": "Synopsis", "type": "long_text", "required": false, "char_limit": 2500, "help": "FOR JUDGING PURPOSES ONLY: Please state the main objective of the entry as concisely as possible. Please include any additional context needed; including cultural background, insights on the creative process, and/or specific notes on what makes the entry unique in the medium entered."}]}, {"key": "where_did_this_run", "label": "Where Did This Run?", "weight": null, "word_limit": null, "scored": false, "sort_order": 3, "guidance": "Please identify where this piece of advertising ran in public, be as specific as possible.", "fields": [{"key": "where_did_this_run", "label": "Where Did This Run?", "type": "long_text", "required": false, "char_limit": 500, "help": "Please identify where this piece of advertising ran in public, be as specific as possible."}]}]}$j$::jsonb),
  ('Integrated', $j${"form_version": 2, "scoring_mode": "weighted", "entry_subject": "campaign", "primary_tool": "section_drafter", "overall": "weighted_average", "source_url": "Clio Awards 2027 entrant portal (new-entries.clios.com, login-walled), read 7 Oct 2026. Record: Award Show Research/EVIDENCE/Clio-Awards-2027-Entry-Form-Capture-2026-10-07.md", "verified_on": "2026-10-07", "notes": "Integrated, verified 7 Oct 2026 in the Clio Awards 2027 entrant portal (draft 243067): the show-level form plus one required field, Mediums (pick at least 3 of 15 portal checkboxes), which is drafted as a list but not scored. Synopsis 2,500 characters, wording identical to the other mediums. The 100% weight on the Synopsis is a Shortlist modelling choice; Clio publishes no section weights for this medium. Shortlist cannot see the work, so the score is a read of the Synopsis only.", "jury_programme_name": "Clio Awards", "jury_entry_noun": "Clio Awards", "jury_framing": "The Clio Awards are judged on the work itself (cover image, executions, and an optional case board and case study video) plus one written field, the Synopsis, which the entry portal labels \"FOR JUDGING PURPOSES ONLY\" and caps at 2,500 characters. You are reading only the Synopsis. You cannot see the work.", "subject_lens": "Score the Synopsis on what the portal asks it to do: \"state the main objective of the entry as concisely as possible\" and give the context a juror needs, \"including cultural background, insights on the creative process, and/or specific notes on what makes the entry unique in the medium entered.\" Reward a clear objective, real cultural or creative-process insight, and a specific case for what is new in this medium. Results are welcome where they help that case but are not the test. Penalise padding, generic claims, and a Synopsis that describes the campaign without saying why it is unique in the medium.", "jury_role": "senior creative juror", "jury_evidence_rule": "- Results are expected but do not dominate at this show: reward a result where it supports the case for the idea, and do not treat its absence as a gap, because results are not the test. Reward specificity about the objective, the cultural context and the creative process; penalise vague superlatives and claims of originality with nothing specific behind them.", "sections": [{"key": "entry_title", "label": "Entry Title", "weight": null, "word_limit": null, "scored": false, "sort_order": 0, "guidance": "The entry title is a short name for this entry. Keep it memorable, descriptive and short. Do not include the brand name, agency name, or medium type. Note: If your piece is awarded, the entry title will be listed on the trophy (maximum characters: 62).", "fields": [{"key": "title", "label": "Entry Title", "type": "short_text", "required": true, "char_limit": 62, "help": "The entry title is a short name for this entry. Keep it memorable, descriptive and short. Do not include the brand name, agency name, or medium type. Note: If your piece is awarded, the entry title will be listed on the trophy (maximum characters: 62)."}]}, {"key": "entry_brand", "label": "Entry Brand", "weight": null, "word_limit": null, "scored": false, "sort_order": 1, "guidance": "The entry brand is the brand, organization, or individual the entry is advertising. (maximum characters: 62).", "fields": [{"key": "brand", "label": "Entry Brand", "type": "short_text", "required": true, "char_limit": 62, "help": "The entry brand is the brand, organization, or individual the entry is advertising. (maximum characters: 62)."}]}, {"key": "synopsis", "label": "Synopsis", "weight": 100, "word_limit": null, "sort_order": 2, "guidance": "FOR JUDGING PURPOSES ONLY: Please state the main objective of the entry as concisely as possible. Please include any additional context needed; including cultural background, insights on the creative process, and/or specific notes on what makes the entry unique in the medium entered.", "fields": [{"key": "synopsis", "label": "Synopsis", "type": "long_text", "required": false, "char_limit": 2500, "help": "FOR JUDGING PURPOSES ONLY: Please state the main objective of the entry as concisely as possible. Please include any additional context needed; including cultural background, insights on the creative process, and/or specific notes on what makes the entry unique in the medium entered."}]}, {"key": "mediums", "label": "Mediums", "weight": null, "word_limit": null, "scored": false, "sort_order": 3, "guidance": "Please select all mediums that apply to execution(s) of this submission (a minimum of three). Options in the portal: Audio, Branded Entertainment & Content, Creative Commerce, Design, Digital/Mobile, Direct, Experience/Activation, Film, Media, Out of Home, Partnerships & Collaborations, Print, Public Relations, Social Media, Use of Influencers. A minimum of 3 options must be selected", "fields": [{"key": "mediums", "label": "Mediums", "type": "list", "required": true, "min_items": 3, "item_label": "Medium", "help": "Please select all mediums that apply to execution(s) of this submission (a minimum of three). Options in the portal: Audio, Branded Entertainment & Content, Creative Commerce, Design, Digital/Mobile, Direct, Experience/Activation, Film, Media, Out of Home, Partnerships & Collaborations, Print, Public Relations, Social Media, Use of Influencers. A minimum of 3 options must be selected"}]}]}$j$::jsonb),
  ('Creative Effectiveness', $j${"form_version": 2, "scoring_mode": "weighted", "entry_subject": "campaign", "primary_tool": "section_drafter", "overall": "weighted_average", "source_url": "Clio Awards 2027 entrant portal (new-entries.clios.com, login-walled), read 7 Oct 2026. Record: Award Show Research/EVIDENCE/Clio-Awards-2027-Entry-Form-Capture-2026-10-07.md; Creative Effectiveness Entrant Brief: https://cdn.clios.com/creativeeffectivenessbrief-white-1_revised.pdf", "verified_on": "2026-10-07", "notes": "Creative Effectiveness, verified 7 Oct 2026: portal draft 243066 (Additional Info identical to Out of Home, Synopsis 2,500 characters) and the Creative Effectiveness Entrant Brief PDF. ONLY the 50% creativity / 50% results split is Clio's (the PDF: \"Judging for this medium is weighted 50% on creativity and 50% on results.\"). Everything else is a Shortlist modelling choice: the Synopsis stands in for the creativity half (50) because that half is judged on the work, which Shortlist cannot see; the four written brief questions split the results half evenly at 12.5 each; Campaign Composition is drafted but not scored, because it is a table of channels, dates and spend and scoring it would reward budget. Never present these as Clio weightings. The PDF upload slot was not seen in the unfilled portal draft: do not tell a customer where to upload the brief. The PDF carries no cycle year. No word or character limits are printed in the PDF.", "jury_programme_name": "Clio Awards", "jury_entry_noun": "Clio Awards Creative Effectiveness", "jury_framing": "Creative Effectiveness at the Clio Awards is judged 50% on creativity and 50% on results. The results half is the five-question Creative Effectiveness Entrant Brief: objectives, strategy, campaign composition, commercial gain, and effect on the market. The creativity half is judged on the work itself, which you cannot see; you are reading the Synopsis in its place.", "subject_lens": "Score the Synopsis on what the portal asks it to do: \"state the main objective of the entry as concisely as possible\" and give the context a juror needs, \"including cultural background, insights on the creative process, and/or specific notes on what makes the entry unique in the medium entered.\" Reward a clear objective, real cultural or creative-process insight, and a specific case for what is new in this medium. Results are welcome where they help that case but are not the test. Penalise padding, generic claims, and a Synopsis that describes the campaign without saying why it is unique in the medium. For the brief sections, the Entrant Brief says: \"Entries will benefit from the ability to isolate ROMI not just sales, and relate results back to the campaign's original objectives.\" For a client whose communications were not for commercial gain, it asks entrants to \"explain the impact it had, e.g. key message penetration or changes to audience behavior.\"", "jury_role": "senior creative juror", "jury_evidence_rule": "- For the Synopsis, results are not the test: reward a clear objective, real insight into the creative process, and a specific case for what makes the work unique. For the brief sections (objectives, strategy, commercial gain, effect on the market), reward specific, attributed results tied back to the original objectives, and an isolated return on marketing investment where the entry supports it, as the Entrant Brief asks; for a non-commercial client, reward evidence of impact such as key message penetration or changes to audience behavior. Penalise vague superlatives and results stated without a source or a link to the objectives.", "sections": [{"key": "entry_title", "label": "Entry Title", "weight": null, "word_limit": null, "scored": false, "sort_order": 0, "guidance": "The entry title is a short name for this entry. Keep it memorable, descriptive and short. Do not include the brand name, agency name, or medium type. Note: If your piece is awarded, the entry title will be listed on the trophy (maximum characters: 62).", "fields": [{"key": "title", "label": "Entry Title", "type": "short_text", "required": true, "char_limit": 62, "help": "The entry title is a short name for this entry. Keep it memorable, descriptive and short. Do not include the brand name, agency name, or medium type. Note: If your piece is awarded, the entry title will be listed on the trophy (maximum characters: 62)."}]}, {"key": "entry_brand", "label": "Entry Brand", "weight": null, "word_limit": null, "scored": false, "sort_order": 1, "guidance": "The entry brand is the brand, organization, or individual the entry is advertising. (maximum characters: 62).", "fields": [{"key": "brand", "label": "Entry Brand", "type": "short_text", "required": true, "char_limit": 62, "help": "The entry brand is the brand, organization, or individual the entry is advertising. (maximum characters: 62)."}]}, {"key": "synopsis", "label": "Synopsis", "weight": 50, "word_limit": null, "sort_order": 2, "guidance": "FOR JUDGING PURPOSES ONLY: Please state the main objective of the entry as concisely as possible. Please include any additional context needed; including cultural background, insights on the creative process, and/or specific notes on what makes the entry unique in the medium entered.", "fields": [{"key": "synopsis", "label": "Synopsis", "type": "long_text", "required": false, "char_limit": 2500, "help": "FOR JUDGING PURPOSES ONLY: Please state the main objective of the entry as concisely as possible. Please include any additional context needed; including cultural background, insights on the creative process, and/or specific notes on what makes the entry unique in the medium entered."}]}, {"key": "objectives", "label": "What were the objectives for the creative work?", "weight": 12.5, "word_limit": null, "sort_order": 3, "guidance": "1. What were the objectives for the creative work? A. Commercial objectives e.g. shareholder value, profit, revenue, sales or share. B. Marketing objectives e.g. penetration, frequency, or maintaining a price premium. C. Communications objectives e.g. awareness, image, attitudes, and behavior.", "fields": [{"key": "commercial", "label": "A. Commercial objectives", "type": "long_text", "required": true, "help": "Please detail the Commercial objectives e.g. shareholder value, profit, revenue, sales or share."}, {"key": "marketing", "label": "B. Marketing objectives", "type": "long_text", "required": true, "help": "Please detail the Marketing objectives e.g. penetration, frequency, or maintaining a price premium."}, {"key": "communications", "label": "C. Communications objectives", "type": "long_text", "required": true, "help": "Please detail the Communications objectives e.g. awareness, image, attitudes, and behavior."}]}, {"key": "strategy", "label": "What was the strategy behind the creative work?", "weight": 12.5, "word_limit": null, "sort_order": 4, "guidance": "Please describe the connection between the objectives, the original client brief and the final creative work that was developed.", "fields": [{"key": "strategy", "label": "Strategy", "type": "long_text", "required": true, "help": "Please describe the connection between the objectives, the original client brief and the final creative work that was developed."}]}, {"key": "composition", "label": "Campaign Composition", "weight": null, "word_limit": null, "scored": false, "sort_order": 5, "guidance": "Please list the different elements of the marketing mix that were used throughout and after your campaign (up to the entry deadline) with an indication of the period.", "fields": [{"key": "composition", "label": "Campaign Composition", "type": "table", "required": true, "min_rows": 1, "help": "Please list the different elements of the marketing mix that were used throughout and after your campaign (up to the entry deadline) with an indication of the period.", "columns": [{"key": "media_channel", "label": "Type of Media / Channel", "type": "text", "required": true, "example": "TV campaign - 3 spots"}, {"key": "dates", "label": "Date of Implementation (start and end, incl. year)", "type": "text", "required": true, "example": "8-10 September 2015"}, {"key": "budget", "label": "Budget or Media Spend", "type": "text", "required": false, "example": "$ 100,000 USD"}, {"key": "region", "label": "Country / Region of Placement", "type": "text", "required": true, "example": "Germany / Europe"}]}]}, {"key": "commercial_gain", "label": "What was the commercial gain for your Client as a result of the campaign?", "weight": 12.5, "word_limit": null, "sort_order": 6, "guidance": "Please provide facts and figures to demonstrate any increases in revenue, profit, return on marketing investment and commercial payback from the communications. Entries will benefit from the ability to isolate ROMI not just sales, and relate results back to the campaign's original objectives. If your communications weren't for commercial gain e.g. for charity or government clients, please explain the impact it had, e.g. key message penetration or changes to audience behavior.", "fields": [{"key": "commercial_gain", "label": "Commercial gain", "type": "long_text", "required": true, "help": "Please provide facts and figures to demonstrate any increases in revenue, profit, return on marketing investment and commercial payback from the communications. Entries will benefit from the ability to isolate ROMI not just sales, and relate results back to the campaign's original objectives. If your communications weren't for commercial gain e.g. for charity or government clients, please explain the impact it had, e.g. key message penetration or changes to audience behavior."}]}, {"key": "market_effect", "label": "What effect did the campaign have on the market?", "weight": 12.5, "word_limit": null, "sort_order": 7, "guidance": "Please explain the impact of the campaign once it went live. Provide details of the effect on the business and on your competitors.", "fields": [{"key": "market_effect", "label": "Effect on the market", "type": "long_text", "required": true, "help": "Please explain the impact of the campaign once it went live. Provide details of the effect on the business and on your competitors. Try to give as many examples as you can on how the communications worked, this will strengthen your entry."}]}]}$j$::jsonb)
) AS v(cat, form)
WHERE sp.id = 24;

DO $post$
BEGIN
  IF (SELECT count(*) FROM show_profiles WHERE show_name = 'Clio Awards') <> 4 THEN
    RAISE EXCEPTION 'CLIO SEED: expected 4 Clio Awards rows';
  END IF;
  IF (SELECT count(*) FROM show_profiles WHERE show_name = 'Clio Awards' AND entry_form IS NULL) <> 0 THEN
    RAISE EXCEPTION 'CLIO SEED: a Clio Awards row has no entry_form';
  END IF;
END $post$;

COMMIT;
